"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7431],{97431:a=>{a.exports=JSON.parse('{"slug":"klyuchevaya-stavka-23-oktyabrya-2026-pauza","locale":"zh","title":"26位经济学家中25位预计央行十月23日维持14%","description":"几乎所有经济学家预计2026年十月23日俄罗斯央行维持14%。解释暂停降息及其对存贷款的意义。","blocks":[{"id":"b001","kind":"paragraph","text":"俄罗斯央行董事会将在2026年十月23日宣布关键利率并更新宏观预测。26位经济学家中25位预计维持14%，一位预计降至13.75%。Sber第一副行长亚历山大\xb7韦佳欣也认为不变最可能。自2025年六月6日开始，利率由21%降至2026年七月14%，九月11日首次暂停。一些经济学家认为暂停可能到年底。2026年最后一次会议在十二月18日。"},{"id":"b002","kind":"paragraph","text":"物价解释了暂停。从一月1日至十月12日涨6.1%，经济发展部估计同比7.22%，央行2026年预测为6–7%。行长纳比乌琳娜九月11日说，降息受利率无法影响的一次性因素阻止，包括生产中断与昂贵燃料。但当时剔除冲击后的持续通胀也估为折年5–6%，高于4%目标。"},{"id":"b003","kind":"paragraph","text":"一次性冲击为何会持续，可看预期。理发师预期租金和染发剂一年涨14%，便现在提高理发价。顾客也预期涨价，今天借钱买电视。价格因大家预期它涨而上涨，这就是通胀预期。九月居民预期未来一年14.2%，八月13.7%，几乎是实际7.22%的两倍。"},{"id":"b004","kind":"paragraph","text":"央行自己还提出一项条件：2027年降息取决于财政赤字是否缩小。政府支出超过收入，会向经济增加需求，使价格涨得更快。"},{"id":"b005","kind":"paragraph","text":"对储户，暂停意味着存款利率维持；九月末10大银行平均最高13.05%。对借款人，普通贷款和市场化房贷仍贵。若十月23日维持，下一次降息机会只有十二月18日。"},{"id":"b006","kind":"paragraph","text":"现在开一年期存款可锁定约13%。若降息比经济学家预计更早，储户获益；若被迫加息，就错过更高利率。借款人等便宜贷款至少需2个月，期间价格继续上涨。十月23日新预测将显示央行准备维持多久。"},{"id":"b007","kind":"heading","text":"2026年十月23日预计作何决定？"},{"id":"b008","kind":"paragraph","text":"几乎一致预计14%不变。26位经济学家中25位如此，一位预计13.75%。Sber同样认为维持最可能。"},{"id":"b009","kind":"heading","text":"俄罗斯央行为何不降息？"},{"id":"b010","kind":"paragraph","text":"年初物价已涨6.1%，接近央行6–7%预测上限。部分是燃料和生产中断的一次性冲击，但居民预计未来一年14.2%，监管机构担心暂时加速变成持续。"},{"id":"b011","kind":"heading","text":"暂停降息对存款和房贷意味着什么？"},{"id":"b012","kind":"paragraph","text":"14%下存款仍有收益，大银行九月末平均最高13.05%；贷款与市场化房贷仍贵。十月23日之后下一决定在十二月18日。"}],"sources":[{"label":"经济学家共识几乎一致预计央行暂停调整","url":"https://www.vedomosti.ru/economics/articles/2026/10/16/1237503-konsensus-prognoz-vedomostei"},{"label":"Sber预计关键利率维持","url":"https://www.kommersant.ru/doc/9026103"},{"label":"Sber预计十月会议维持利率","url":"https://www.interfax.ru/business/1122297"},{"label":"2026年九月通胀预期与消费者情绪","url":"https://www.cbr.ru/analytics/dkp/inflationary_expectations/Infl_exp_26-09/"},{"label":"俄罗斯十月6日至12日通胀0.11%","url":"https://www.interfax.ru/business/1122459"},{"label":"央行公布2026年关键利率会议日历","url":"https://finance.mail.ru/article/bank-rossii-opublikoval-grafik-zasedaniy-po-klyuchevoy-stavke-na-2026-god-68067122/"},{"label":"十大银行平均最高存款利率升至13.05%","url":"https://ria.ru/20261001/bank-2121443529.html"},{"label":"央行将关键利率降至20%","url":"https://finance.mail.ru/article/bank-rossii-snizil-klyuchevuyu-stavku-do-20-godovyh-66466367/"},{"label":"央行上调2026年通胀预测","url":"https://www.kommersant.ru/doc/8843971"}],"sourceBodySha256":"fe62eaf826a4de568479af2c8bab712a15f8ab8a8d9f9a89aca0a2ed2e59bfc4"}')}}]);